        _chartSummary(state) {
            const ds = (state && state.domainState) || {};
            const rates = ds.rateHistory || [];
            const infl = ds.inflationHistory || [];
            if (!rates.length) return this._t('chart_alt_empty');
            const self = this;
            const parts = rates.map(function(r, i) {
                return self._meetingLabel(i) + ': ' + self._n(r, 2) + '% / ' + self._n(infl[i] !== undefined ? infl[i] : 0, 1) + '%';
            });
            return this._t('chart_alt_prefix') + ' ' + parts.join('; ');
        }

