            const live = function() { return (window.mySimulation && window.mySimulation.state) || {}; };
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            // the briefing follows the framework round counter: no timer, one source of truth
            uiManager.bind('roundTitle', 'currentPeriod', function() { self._updateBriefing(live()); return self._roundTitle(live()); });
