            uiManager.bind('coreInflationDisplay', 'domainState.displayCoreInflation', (v) => self._n(v, 1) + '%');
            uiManager.bind('gdpDisplay', 'domainState.displayGdp', (v) => self._n(v, 1) + '%');
            uiManager.bind('unemploymentDisplay', 'domainState.displayUnemployment', (v) => self._n(v, 1) + '%');
            uiManager.bind('outputGapDisplay', 'domainState.displayOutputGap', (v) => self._signed(v, 1) + '%');
