                const repaint = function() {
                    try {
                        const fw = window.mySimulation;
                        if (!fw || !fw.state) return;
                        self._updateBriefing(fw.state);
                        if (fw.uiManager && typeof fw.uiManager.updateFromState === 'function') fw.uiManager.updateFromState(fw.state);
                        if (typeof fw.updateCharts === 'function') fw.updateCharts();
                        if (typeof fw.renderHistoryTable === 'function') fw.renderHistoryTable();
                    } catch (e) { /* never break the page on a repaint */ }
                };
                document.addEventListener('express:langchanged', repaint);
                const fw0 = window.mySimulation;
                if (fw0 && fw0.eventBus && typeof fw0.eventBus.on === 'function') {
                    fw0.eventBus.on('language:changed', repaint);
                    fw0.eventBus.on('period:submitted', repaint);
