        getHint(state, results) {
            if (!results) return null;
            if (results.scoreImpact <= -10) return this._t('hint_low_credibility');
            if (results.scoreImpact >= 14) return this._t('hint_on_curve');
            if (state.domainState.currentRate >= 5.0) return this._t('hint_high_rate');
            if (state.domainState.currentRate <= 2.0) return this._t('hint_low_rate');
            return null;
        }

