                { key: 'results.rateChangeBps', label: 'Move (bps)', i18nKey: 'col_move',
                  formatter: (v) => (v > 0 ? '+' : v < 0 ? '−' : '') + Math.abs(v) + ' ' + this._t('unit_bps') },
                { key: 'results.newRate', label: 'New Rate', i18nKey: 'col_new_rate',
