        getPresets() { return null; }

        // band, label, turning point and insights all come from this one reading of the run
        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            const self = this;
            const rows = history.map(function(h) { return (h && h.results) || {}; });
            const n = rows.length;
            const num = function(v) { return (typeof v === 'number' && isFinite(v)) ? v : 0; };
            const total = rows.reduce(function(s, r) { return s + num(r.scoreImpact); }, 0);
            const last = rows[n - 1];
            const overall = this._composite(total, n);
            const performance = this._tier(overall);
            const perfKey = 'perf_' + performance;

            const movePts = rows.reduce(function(s, r) { return s + num(r.movePts); }, 0);
            const tonePts = rows.reduce(function(s, r) { return s + num(r.tonePts) + num(r.brokenPts); }, 0);
            const legacyPts = rows.reduce(function(s, r) { return s + num(r.legacyPts); }, 0);
            const rateScore = Math.max(0, Math.min(100, Math.round(((movePts + 18 * n) / (30 * n)) * 100)));
            const statementScore = Math.max(0, Math.min(100, Math.round(((tonePts + 6 * n) / (11 * n)) * 100)));

            // what each meeting cost: points left on the table that day, plus what its stance cost a year later
            const costs = rows.map(function(r, i) {
                const later = rows[i + 2] ? -num(rows[i + 2].legacyPts) : 0;
                return (17 - num(r.movePts) - num(r.tonePts)) - num(r.brokenPts) + later;
            });
            const tagCost = {};
            const tagAt = {};
            rows.forEach(function(r, i) {
                const tags = [];
                if (r.mistakeTag) tags.push(r.mistakeTag);
                if (num(r.brokenPts) < 0) tags.push('broken');
                tags.forEach(function(tg) {
                    const c = tg === 'broken' ? -num(r.brokenPts) : costs[i] + num(r.brokenPts);
                    if (tagCost[tg] === undefined || c > tagCost[tg]) { tagCost[tg] = c; tagAt[tg] = i; }
                });
            });
            const tags = Object.keys(tagCost).sort(function(a, b) { return tagCost[b] - tagCost[a]; });

            let turningPoint = this._t('turn_none');
            let worst = -1;
            costs.forEach(function(c, i) { if (c > worst) worst = c; });
            if (tags.length && worst >= 7) {
                const tg = tags[0];
                turningPoint = this._fill(this._t('turn_at'), { meeting: this._meetingLabel(tagAt[tg]) }) + ' ' + this._t('ins_' + tg);
            }
            const insights = [];
            tags.slice(tags.length && worst >= 7 ? 1 : 0, 4).forEach(function(tg) { insights.push(self._t('ins_' + tg)); });
            if (!tags.length) insights.push(this._t('ins_clean'));
            if (legacyPts < 0) insights.push(this._fill(this._t('ins_legacy'), { pts: String(Math.abs(legacyPts)) }));
            insights.push(this._fill(this._t('ins_path'), {
                start: this._n(this.START_RATE, 2) + '%', end: this._n(num(last.newRate), 2) + '%',
                infl: this._n(num(last.effectiveInflation), 1) + '%' }));
            insights.push(this._fill(this._t('ins_split'), { rate: String(rateScore), tone: String(statementScore) }));

            return {
                composite: overall,
                overallScore: overall,
                totalScore: overall,
                score: overall,
                totalCredibilityDelta: total,
                finalCredibility: last.credibility !== undefined ? last.credibility : 100,
                finalRate: last.newRate !== undefined ? last.newRate : this.START_RATE,
                finalInflation: num(last.effectiveInflation),
                rateScore: rateScore,
                statementScore: statementScore,
                legacyPoints: legacyPts,
                meetings: n,
                performance: performance,
                performanceKey: perfKey,
                performanceLabel: this._t(perfKey),
                turningPoint: turningPoint,
                insights: insights.slice(0, 5),
                questions: [this._t('question_1'), this._t('question_2'), this._t('question_3')]
            };
        }

        _t(key) {
            if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                const v = window.mySimulation.t(key);
                if (v) return v;
            }
            return key;
        }

        formatCompletionMessage(summary) {
            const s = summary || {};
            const t = this._t.bind(this);
            const self = this;
            const esc = function(v) {
                return String(v === undefined || v === null ? '' : v)
                    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
            };
            const num = function(v, dp) { return (typeof v === 'number') ? self._n(v, dp) : '-'; };
            const rows = [
                [t('debrief_rate_score'), esc(s.rateScore !== undefined ? s.rateScore : 0) + '/100'],
                [t('debrief_statement_score'), esc(s.statementScore !== undefined ? s.statementScore : 0) + '/100'],
                [t('debrief_cred'), esc(self._signed(s.totalCredibilityDelta || 0, 0))],
                [t('debrief_final_cred'), esc(Math.round(s.finalCredibility || 0))],
                [t('debrief_final_rate'), num(s.finalRate, 2) + '%'],
                [t('debrief_final_infl'), num(s.finalInflation, 1) + '%']
            ].map(function(r) {
                return '<li><span class="bccmpc-sim-debrief-k">' + esc(r[0]) + '</span>' +
                       '<span class="bccmpc-sim-debrief-v">' + r[1] + '</span></li>';
            }).join('');
            const ins = (s.insights || []).map(function(x) { return '<li>' + esc(x) + '</li>'; }).join('');
            const qs = (s.questions || []).map(function(x) { return '<li>' + esc(x) + '</li>'; }).join('');
            return '<div class="bccmpc-sim-debrief">' +
                     '<h3>' + esc(t('debrief_heading')) + '</h3>' +
                     '<p class="bccmpc-sim-debrief-headline">' + esc(t('debrief_score')) + ' <strong>' +
                       esc(s.overallScore || 0) + '/100</strong> &middot; ' + esc(s.performanceLabel || '') + '</p>' +
                     '<ul class="bccmpc-sim-debrief-list">' + rows + '</ul>' +
                     '<h4 class="bccmpc-sim-debrief-sub">' + esc(t('debrief_turning')) + '</h4>' +
                     '<p class="bccmpc-sim-debrief-turn">' + esc(s.turningPoint || '') + '</p>' +
                     '<h4 class="bccmpc-sim-debrief-sub">' + esc(t('debrief_insights')) + '</h4>' +
                     '<ul class="bccmpc-sim-debrief-insights">' + ins + '</ul>' +
                     '<h4 class="bccmpc-sim-debrief-sub">' + esc(t('debrief_questions')) + '</h4>' +
                     '<ol class="bccmpc-sim-debrief-questions">' + qs + '</ol>' +
                   '</div>';
        }

